contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint w) public payable {
        bool firstOk;
        c.SetMinSum(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstOk = false; } else { firstOk = true; }

        bool secondOk;
        c.SetMinSum(w); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondOk = false; } else { secondOk = true; }

        uint afterVal = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(firstOk && secondOk ? afterVal == w : true);
    }

    receive() external payable {}
}

