pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v, uint256 w) internal {
        bool firstOk;
        try c.SetMinSum(v) { firstOk = true; } catch { firstOk = false; }
        bool secondOk;
        try c.SetMinSum(w) { secondOk = true; } catch { secondOk = false; }
        uint256 afterVal;
        try c.MinSum() returns (uint256 __r) { afterVal = __r; } catch { return; }
        assertTrue(firstOk && secondOk ? afterVal == w : true);
    }

    function testFuzz_run(uint256 v, uint256 w) public {
        _run(v, w);
    }

    receive() external payable {}
}
